Complete local C example; the app itself does not execute it:
```c
#include <stdio.h>
#include <stdlib.h>
#if defined(__STDC_NO_THREADS__) && __STDC_NO_THREADS__
#error C threads unavailable on this implementation
#endif
#include <threads.h>
static mtx_t lock;
static int count;
static void increment(void) {
    if (mtx_lock(&lock) != thrd_success) abort();
    count++;
    if (mtx_unlock(&lock) != thrd_success) abort();
}
static int work(void *unused) {
    (void)unused;
    for (int i = 0; i < 1000; i++) increment();
    return 0;
}
int main(void) {
    thrd_t worker;
    if (mtx_init(&lock, mtx_plain) != thrd_success) return 1;
    if (thrd_create(&worker, work, NULL) != thrd_success) {
      mtx_destroy(&lock); return 1;
    }
    for (int i = 0; i < 1000; i++) increment();
    if (thrd_join(worker, NULL) != thrd_success) abort();
    printf("%d\n", count);
    mtx_destroy(&lock);
    return 0;
}
```

